import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { AutoMode, Check, Issue, Proposal, WordResult, WordTarget } from '../types'

const HAIKU = 'haiku'
// Prompts longer than this (pasted logs, files) are sent as they are.
const AUTOFIX_MAX = 6000
// How long a send may wait for Haiku in `auto ai` before the rules fix is used instead.
const AUTO_AI_TIMEOUT_MS = 15_000

const check = atom({ plugin: 'grammar-guard', key: 'check' } as const, null)
const autoMode = atom({ plugin: 'grammar-guard', key: 'autoMode' } as const, 'off')
const busy = atom({ plugin: 'grammar-guard', key: 'busy' } as const, null)
const note = atom({ plugin: 'grammar-guard', key: 'note' } as const, '')
const undo = atom({ plugin: 'grammar-guard', key: 'undo' } as const, null)
const word = atom({ plugin: 'grammar-guard', key: 'word' } as const, null)
const wordResult = atom({ plugin: 'grammar-guard', key: 'wordResult' } as const, null)

type $ = EngineInterface

// --- the helper (bin/gp.py): the no-AI work --------------------------------

async function helper($: $, args: string[], stdin?: string, timeoutMs = 30_000): Promise<Record<string, unknown>> {
  let r: Awaited<ReturnType<$['process']['run']>>
  try {
    r = await $.process.run(['python3', `${$.plugin.root}/bin/gp.py`, ...args], {
      stdin: stdin ?? '',
      timeoutMs,
    })
  } catch (err) {
    return { error: `helper did not run: ${String(err instanceof Error ? err.message : err)}` }
  }
  try {
    return JSON.parse(r.stdout) as Record<string, unknown>
  } catch {
    return { error: (r.stderr || r.stdout || `exit ${r.exitCode}`).slice(0, 300) }
  }
}

async function runCheck($: $, text: string): Promise<Check | string> {
  const r = await helper($, ['check'], text)
  if (typeof r.error === 'string') return r.error
  return { text, engine: String(r.engine), issues: r.issues as Issue[] }
}

async function runFix($: $, text: string): Promise<{ text: string; count: number; engine: string } | string> {
  const r = await helper($, ['fix'], text)
  if (typeof r.error === 'string') return r.error
  return { text: String(r.text), count: (r.applied as unknown[]).length, engine: String(r.engine) }
}

/** "N fix(es)", and why it was spelling only when LanguageTool wasn't up (stopped while idle, or starting). */
function fixCount(r: { count: number; engine: string }): string {
  const spellingOnly = r.engine === 'hunspell' ? ' (spelling only: LanguageTool was not up; it is starting)' : ''
  return `${r.count} fix(es)${spellingOnly}`
}

// --- Haiku ---------------------------------------------------------------

async function haiku($: $, system: string, prompt: string, maxTokens = 1500, timeoutMs = 60_000): Promise<string> {
  const r = await $.model.complete({ model: HAIKU, system, prompt, maxTokens, timeoutMs })
  if (!r.isAnswered) throw new Error(`Haiku did not answer (${r.reason})`)
  return r.text.trim()
}

function jsonList(text: string): string[] {
  const m = text.match(/\[[\s\S]*\]/)
  if (!m) return []
  try {
    const v = JSON.parse(m[0]) as unknown
    return Array.isArray(v) ? v.map(String).filter(Boolean) : []
  } catch {
    return []
  }
}

const DRAFT_SYSTEM =
  'You edit a message the user is about to send to an AI coding assistant. The text may come from ' +
  'speech dictation, so expect misheard words and homophones. Never answer or act on the message; ' +
  'return only the edited message text, with no preamble, quotes or notes. Keep code, paths, ' +
  'identifiers and technical terms exactly as written.'

const LEVELS: Record<Proposal['level'], string> = {
  light:
    'Make the minimum changes: fix spelling, grammar, punctuation and dictation mistakes. Keep the ' +
    'wording, tone and sentence order.',
  medium:
    'Fix errors as above, and rearrange clauses and subordinate sentences where that makes the ' +
    'message clearer. Keep the vocabulary, tone and every point; add nothing. The project terms ' +
    'below are names used in this project: where a word or phrase in the message is a near miss of ' +
    'one (likely misheard), use the project spelling; never add a term the message does not mention.',
  complete:
    'Rewrite the message freely for clarity and concision, using the conversation and the project ' +
    'terms below to choose precise wording. Keep every request, question and constraint; add no new ' +
    'ones.',
}

async function projectTerms($: $): Promise<string[]> {
  const v = await helper($, ['vocab', await $.session.cwd()])
  return Array.isArray(v.terms) ? (v.terms as string[]) : []
}

/** Medium gets the project terms; complete gets the recent conversation too. Light gets neither. */
async function contextFor($: $, level: 'medium' | 'complete'): Promise<string> {
  const terms = `<project_terms>\n${(await projectTerms($)).join(', ')}\n</project_terms>\n\n`
  if (level === 'medium') return terms
  const msgs = await $.session.messages()
  const recent = msgs
    .filter(m => m.text.trim())
    .slice(-8)
    .map(m => `${m.role.toUpperCase()}: ${m.text.slice(0, 1500)}`)
    .join('\n\n')
  return `<conversation>\n${recent || '(none yet)'}\n</conversation>\n${terms}`
}

// --- small text helpers -----------------------------------------------------

function escapeRe(s: string) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/** Replaces the first whole-word `from` in `text`, or appends `to` when absent. */
function swapWord(text: string, from: string, to: string): string {
  const re = new RegExp(`(^|[^\\p{L}\\p{N}_])${escapeRe(from)}(?![\\p{L}\\p{N}_])`, 'iu')
  if (from && re.test(text)) return text.replace(re, (_m, pre: string) => pre + to)
  return text ? `${text.replace(/\s+$/, '')} ${to}` : to
}

/** The language the translate tool works from (GP_NATIVE_LANG, e.g. "it"); empty means Haiku detects it. */
async function nativeLang($: $): Promise<string> {
  return ((await $.env.get('GP_NATIVE_LANG')) ?? '').trim().toLowerCase()
}

const langPair = (lang: string) => `${lang ? lang.toUpperCase() : 'any'}→EN`

/** Pulls English candidates out of a FreeDict entry ("1. dog", "dog; hound"). */
function entryWords(entry: string): string[] {
  const lines = entry.split('\n').slice(1)
  const out: string[] = []
  for (const l of lines) {
    const body = l.replace(/^\s*\d+\.\s*/, '').replace(/\(.*?\)|\[.*?\]|<.*?>/g, '').trim()
    if (!body || /^(see|syn|note|pl\.)/i.test(body)) continue
    for (const w of body.split(/[;,]/)) {
      const t = w.trim()
      if (t && t.length < 40 && !out.includes(t)) out.push(t)
    }
  }
  return out.slice(0, 12)
}

// --- word tools and drafts -------------------------------------------------

type WordTool = 'tr' | 'syn' | 'project'
const WORD_TOOL_NAMES: Record<WordTool, string> = { tr: 'Translate', syn: 'Synonyms', project: 'Project term' }

async function lookupWord($: $, tool: WordTool, q: string, draft: string): Promise<WordResult> {
  if (!q) throw new Error('type a word or phrase first')
  let res: WordResult
  if (tool === 'tr') {
    const r = await helper($, ['tr', q])
    const lang = await nativeLang($)
    const entries = Array.isArray(r.entries) ? (r.entries as string[]) : []
    const fromDict = entries.flatMap(entryWords)
    if (fromDict.length) {
      res = { title: `${q} (${langPair(lang)}, dictionary)`, items: [...new Set(fromDict)], detail: entries.join('\n\n') }
    } else {
      const from = lang ? `from the language with ISO code "${lang}"` : 'from whatever language it is in'
      const ai = await haiku(
        $,
        `Translate the user's word or phrase ${from} into English. Reply with a JSON array of up to 5 English ` +
          'options, most natural first, nothing else.',
        q,
        300,
      )
      res = { title: `${q} (${langPair(lang)}, Haiku)`, items: jsonList(ai) }
    }
  } else if (tool === 'syn') {
    const r = await helper($, ['syn', q])
    if (typeof r.error === 'string') throw new Error(r.error)
    const groups = (r.groups ?? {}) as Record<string, string[]>
    res = {
      title: `Synonyms of ${q}`,
      items: [...new Set(Object.values(groups).flat())].slice(0, 24),
      detail: Object.entries(groups).map(([pos, ws]) => `${pos}: ${ws.join(', ')}`).join('\n'),
    }
  } else {
    const terms = await projectTerms($)
    if (!terms.length) throw new Error('no project terms found in this folder')
    const ai = await haiku(
      $,
      'You match meaning, not spelling. From the project term list, pick the terms whose meaning best ' +
        'matches what the user describes (in English or in their own language). Reply with a JSON ' +
        'array of up to 6 terms copied exactly from the list, best first; [] if none fit.',
      `<project_terms>\n${terms.join(', ')}\n</project_terms>\n<looking_for>\n${q}\n</looking_for>\n<draft>\n${draft}\n</draft>`,
      300,
    )
    res = { title: `Project terms for “${q}”`, items: jsonList(ai) }
  }
  if (!res.items.length) res.detail = res.detail ?? 'No results.'
  return res
}

async function makeDraft($: $, level: Proposal['level'], text: string): Promise<string> {
  if (!text.trim()) throw new Error('nothing to rewrite yet')
  const ctx = level === 'light' ? '' : await contextFor($, level)
  return haiku($, `${DRAFT_SYSTEM}\n\n${LEVELS[level]}`, `${ctx}<message>\n${text}\n</message>`)
}

// --- the prompt box (terminal) ----------------------------------------------

// The live check's debounce; a module variable, so a reload simply drops it.
let checkTimer: { cancel: () => void } | null = null
// What `/grammar-guard auto` reports about the last prompt sent.
let lastSend = 'nothing sent since the mod loaded'

const LEVEL_NAMES = ['light', 'medium', 'complete'] as const

function isLevel(s: string): s is Proposal['level'] {
  return (LEVEL_NAMES as readonly string[]).includes(s)
}

/** The checked issues, moved onto `text` when it changed since the check. */
function placeIssues(c: Check, text: string): Issue[] {
  const delta = text.length - c.text.length
  const out: Issue[] = []
  let from = 0
  for (const it of c.issues) {
    const len = it.end - it.start
    if (!it.word) continue
    let at = -1
    for (const s of [it.start, it.start + delta]) {
      if (s >= from && text.slice(s, s + len) === it.word) {
        at = s
        break
      }
    }
    if (at < 0) {
      const near = text.indexOf(it.word, Math.max(from, it.start - Math.abs(delta) - 8))
      if (near >= 0 && Math.abs(near - it.start) <= Math.abs(delta) + 8) at = near
    }
    if (at < 0) continue
    out.push({ ...it, start: at, end: at + len })
    from = at + len
  }
  return out
}

function decorationsFor(issues: Issue[]) {
  return issues.map(it => ({
    start: it.start,
    end: it.end,
    underline: true,
    color: it.kind === 'style' ? 'warning' : 'error',
  }))
}

/** Checks the box; repaints it at once when the caret is at the end, else at the next key. */
async function checkBox($: $) {
  const box = await $.prompt.read()
  if (!box.text.trim()) {
    await update($, check, () => null)
    return
  }
  const c = await runCheck($, box.text)
  if (typeof c === 'string') {
    await update($, note, () => c)
    return
  }
  await update($, check, () => c)
  const now = await $.prompt.read()
  if (now.text === c.text && now.cursor === now.text.length && c.issues.length) {
    await $.prompt.fill({ text: c.text, mode: 'replace', decorations: decorationsFor(c.issues) })
  }
}

/** Replaces the box, keeping the old text for Undo, and checks the new one. */
async function replaceBox($: $, text: string) {
  const box = await $.prompt.read()
  await update($, undo, () => box.text)
  await $.prompt.fill({ text, mode: 'replace' })
  await checkBox($)
}

async function withBusy($: $, label: string, fn: () => Promise<void>) {
  if (await read($, busy)) return
  await update($, busy, () => label)
  await update($, note, () => '')
  try {
    await fn()
  } catch (err) {
    await update($, note, () => `${label} failed: ${String(err instanceof Error ? err.message : err)}`)
  } finally {
    await update($, busy, () => null)
  }
}

/** The word the caret is on or just after, as offsets into the box. */
function wordAt(text: string, cursor: number): WordTarget | null {
  for (const m of text.matchAll(/[\p{L}\p{N}][\p{L}\p{N}'_-]*/gu)) {
    const start = m.index ?? 0
    const end = start + m[0].length
    if (cursor >= start && cursor <= end) return { word: m[0], start, end }
  }
  return null
}

// Per session on purpose: parallel sessions each keep their own switch, off at start.
async function setAutoMode($: $, mode: AutoMode) {
  await update($, autoMode, () => mode)
}

const MODE_NAMES: Record<AutoMode, string> = {
  off: 'OFF',
  on: 'ON (rules, no AI)',
  ai: 'AI (Haiku light fix, rules as fallback)',
}

/** Why Haiku's version of `before` can't be sent in its place, or null when it can. */
function rejectAiFix(before: string, after: string): string | null {
  if (!after.trim()) return 'empty reply'
  const ratio = after.length / before.length
  // Short messages swing more in length from a single fix.
  const slack = before.length < 40 ? 0.6 : 0.35
  if (ratio < 1 - slack || ratio > 1 + slack) return 'reply length far from the message (an answer, not an edit?)'
  for (const code of before.match(/`[^`\n]+`/g) ?? []) {
    if (!after.includes(code)) return `code span ${code} changed`
  }
  return null
}

/** The `auto ai` fix: Haiku's light draft, else the rules fix. */
async function aiFix($: $, text: string): Promise<{ text: string; how: string }> {
  if (text.includes('```')) {
    const r = await runFix($, text)
    return typeof r === 'string' ? { text, how: `sent unchanged: ${r}` } : { text: r.text, how: `rules (has code block), ${fixCount(r)}` }
  }
  let why: string
  try {
    const out = (await haiku($, `${DRAFT_SYSTEM}\n\n${LEVELS.light}`, `<message>\n${text}\n</message>`, 2000, AUTO_AI_TIMEOUT_MS))
      .replace(/^<message>\s*|\s*<\/message>$/g, '')
    const reject = rejectAiFix(text, out)
    if (!reject) return { text: out, how: out === text ? 'Haiku: no changes' : 'Haiku light fix applied' }
    why = reject
  } catch (err) {
    why = String(err instanceof Error ? err.message : err)
  }
  const r = await runFix($, text)
  if (typeof r === 'string') return { text, how: `Haiku not used (${why}); sent unchanged: ${r}` }
  return { text: r.text, how: `Haiku not used (${why}); rules fix, ${fixCount(r)}` }
}

// --- /grammar-guard -------------------------------------------------------------

const HELP = [
  'grammar-guard commands:',
  '  /grammar-guard auto on|ai|off            fix what you send, in this session: on = grammar rules,',
  '                                         ai = Haiku light fix (catches dictation slips)',
  '  /grammar-guard auto                      show the setting and what the last send did',
  '  /grammar-guard draft light|medium|complete <text>   a Haiku draft of <text>',
  '  /grammar-guard terms                     the project terms medium and complete drafts use',
  'In the terminal: issues are underlined in the prompt box, and the band above it has',
  'Autocorrect, drafts, word tools and the auto-fix switch (ctrl+x tab to reach it).',
].join('\n')

async function termsReport($: $): Promise<string> {
  const v = await helper($, ['vocab', await $.session.cwd()])
  if (typeof v.error === 'string') return `Project terms failed: ${v.error}`
  const group = (name: string, key: string) => {
    const xs = Array.isArray(v[key]) ? (v[key] as string[]) : []
    return `${name} (${xs.length}): ${xs.join(', ') || '(none)'}`
  }
  return [
    `Project terms for ${String(v.root)}, as medium and complete drafts send them to Haiku:`,
    group('Phrases', 'phrases'),
    group('Files', 'files'),
    group('Words', 'words'),
    v.dictionary ? '' : 'hunspell is missing, so words are kept by shape only (camelCase, snake_case, digits).',
    `Stored in ${String(v.cache)} (only you can read it). Rebuilt after 10 minutes; deleted when the`,
    'session ends, or after a day if a session ended without cleaning up.',
  ]
    .filter(Boolean)
    .join('\n')
}

async function runCommand($: $, args: string): Promise<string> {
  const [sub = '', ...rest] = args.trim().split(/\s+/)
  if (sub === 'auto') {
    const want = rest[0]?.toLowerCase()
    if (want === 'on' || want === 'off' || want === 'ai') await setAutoMode($, want)
    else if (want) return 'Usage: /grammar-guard auto on|ai|off'
    const mode = await read($, autoMode)
    return `Auto-fix on send is ${MODE_NAMES[mode]} in this session. Last send: ${lastSend}.`
  }
  if (sub === 'draft') {
    const level = (rest[0] ?? '').toLowerCase()
    const text = args.trim().replace(/^draft\s+\S+\s*/, '')
    if (!isLevel(level) || !text) return 'Usage: /grammar-guard draft light|medium|complete <your text>'
    try {
      return await makeDraft($, level, text)
    } catch (err) {
      return `Draft failed: ${String(err instanceof Error ? err.message : err)}`
    }
  }
  if (sub === 'terms') return termsReport($)
  const mode = await read($, autoMode)
  return `${HELP}\n\nAuto-fix on send is ${MODE_NAMES[mode]} in this session.`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'grammar-guard',
      description: 'Grammar guard: auto on|ai|off, draft light|medium|complete <text>',
      argumentHint: 'auto on|ai|off · draft <level> <text>',
    })
    // Deletes term lists older than a day, and starts LanguageTool if it is installed and not
    // running (checks use hunspell until it is up). The helper stops it after 30 idle minutes.
    await helper($, ['session-start'])
    return next(e)
  })

  // The folder's term list goes with the session. Exit gives the whole chain a short time
  // budget, so the helper gets 2 s; a list left behind is pruned at the next session start.
  on('session.end', async ($, e, next) => {
    await helper($, ['vocab-drop', await $.session.cwd()], '', 2_000)
    return next(e)
  })

  on('command.run', { command: 'grammar-guard' }, async ($, e) => ({ text: await runCommand($, e.args) }))

  // E: grammar auto-fix on what the person sends, when switched on.
  on('prompt.submit', async ($, e, next) => {
    const kind = e.origin?.kind ?? 'none'
    const isPersons = kind === 'composer' || kind === 'sdk' || kind === 'bridge'
    if (!isPersons) return next(e)
    // A sent prompt ends word mode: its word offsets belonged to the old text.
    await update($, word, () => null)
    const mode = await read($, autoMode)
    if (mode === 'off') {
      lastSend = `from ${kind}, auto-fix was off`
      return next(e)
    }
    if (e.text.startsWith('/') || e.text.length > AUTOFIX_MAX || !e.text.trim()) {
      lastSend = `from ${kind}, skipped (command, empty or over ${AUTOFIX_MAX} chars)`
      return next(e)
    }
    let text = e.text
    if (mode === 'ai') {
      const r = await aiFix($, e.text)
      text = r.text
      lastSend = `from ${kind}, ${r.how}`
    } else {
      const r = await runFix($, e.text)
      if (typeof r === 'string') lastSend = `from ${kind}, sent unchanged: ${r}`
      else {
        text = r.text
        lastSend = `from ${kind}, ${fixCount(r)} applied`
      }
    }
    await update($, check, () => null)
    await update($, undo, () => null)
    return next({ ...e, text })
  })

  // A: issues underlined in the prompt box itself (terminal only: no other surface raises it).
  on('prompt.edit', async ($, e, next) => {
    const r = await next(e)
    checkTimer?.cancel()
    checkTimer = $.clock.after(800, () => void checkBox($))
    const c = await read($, check)
    if (!c || !r.text.trim()) return r
    return { ...r, decorations: [...(r.decorations ?? []), ...decorationsFor(placeIssues(c, r.text))] }
  })

  // C, D, E and B's entry point: the band above the prompt box.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const c = await read($, check)
    const mode = await read($, autoMode)
    const running = await read($, busy)
    const msg = await read($, note)
    const before = await read($, undo)
    const issues = c ? c.issues : []

    const fixIssue = (it: Issue, to: string) =>
      withBusy($, 'Fix', async () => {
        const box = await $.prompt.read()
        const cur = c ? placeIssues({ ...c, issues: [it] }, box.text)[0] : undefined
        if (!cur) throw new Error('the text changed; wait for the next check')
        await replaceBox($, box.text.slice(0, cur.start) + to + box.text.slice(cur.end))
      })

    const autocorrect = () =>
      withBusy($, 'Autocorrect', async () => {
        const box = await $.prompt.read()
        if (!box.text.trim()) throw new Error('the prompt box is empty')
        const r = await runFix($, box.text)
        if (typeof r === 'string') throw new Error(r)
        if (!r.count) {
          await update($, note, () => 'Autocorrect: nothing to fix.')
          return
        }
        await replaceBox($, r.text)
        await update($, note, () => `Autocorrect: ${r.count} change(s) · u undoes`)
      })

    const draft = (level: Proposal['level']) =>
      withBusy($, `Draft (${level})`, async () => {
        const box = await $.prompt.read()
        await replaceBox($, await makeDraft($, level, box.text))
        await update($, note, () => `Draft (${level}) is in the box · u undoes`)
      })

    // The word tools live in the band, not a pane: a pane only gets the keyboard over an
    // empty prompt box, and here the box always holds text, so its keys went into the box.
    const openWord = () =>
      withBusy($, 'Word', async () => {
        const box = await $.prompt.read()
        const target = wordAt(box.text, box.cursor)
        if (!target) throw new Error('put the cursor on a word first')
        await update($, word, () => target)
        await update($, wordResult, () => null)
      })

    const closeWord = async () => {
      await update($, word, () => null)
      await update($, wordResult, () => null)
    }

    const restore = () =>
      withBusy($, 'Undo', async () => {
        if (before === null) return
        await $.prompt.fill({ text: before, mode: 'replace' })
        await update($, undo, () => null)
        await checkBox($)
      })

    // B: the word tools, for the word under the cursor, in place of the band's usual rows.
    const target = await read($, word)
    if (target) {
      const res = await read($, wordResult)
      const lang = await nativeLang($)

      const lookup = (tool: WordTool) =>
        withBusy($, WORD_TOOL_NAMES[tool], async () => {
          const box = await $.prompt.read()
          await update($, wordResult, () => null)
          const r = await lookupWord($, tool, target.word, box.text)
          await update($, wordResult, () => r)
        })

      const pick = (choice: string) =>
        withBusy($, 'Replace', async () => {
          const box = await $.prompt.read()
          const isSame = box.text.slice(target.start, target.end) === target.word
          const text = isSame
            ? box.text.slice(0, target.start) + choice + box.text.slice(target.end)
            : swapWord(box.text, target.word, choice)
          await closeWord()
          await replaceBox($, text)
        })

      return (
        <Box flexDirection="column">
          <Box flexDirection="row" flexWrap="wrap" columnGap={1}>
            <Text bold>{target.word}</Text>
            <Button key="tr" label={`Translate ${langPair(lang)}`} hotkey="t" onPress={() => void lookup('tr')} />
            <Button key="syn" label="Synonyms" hotkey="s" onPress={() => void lookup('syn')} />
            <Button key="project" label="Project term" hotkey="p" onPress={() => void lookup('project')} />
            <Button key="back" label="Back" hotkey="b" dimColor onPress={() => void closeWord()} />
            {running || msg ? <Text dimColor>{running ? `${running}…` : msg}</Text> : null}
          </Box>
          {res ? (
            <Box flexDirection="row" flexWrap="wrap" columnGap={1}>
              <Text dimColor>{res.items.length ? `${res.title}:` : `${res.title}: ${res.detail ?? 'no results'}`}</Text>
              {res.items.map((it, i) => (
                <Button
                  key={`pick-${i}`}
                  label={it}
                  hotkey={i < 9 ? String(i + 1) : undefined}
                  onPress={() => void pick(it)}
                />
              ))}
            </Box>
          ) : null}
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" flexWrap="wrap" columnGap={1}>
          {issues.length > 0 ? (
            <Text color="error">{issues.length} issue(s):</Text>
          ) : (
            <Text dimColor>{c ? `no issues · ${c.engine}` : 'grammar-guard'}</Text>
          )}
          {issues.slice(0, 3).map((it, i) =>
            it.replacements[0] !== undefined ? (
              <Button
                key={`fix-${i}`}
                label={`${it.word}→${it.replacements[0] || '(remove)'}`}
                hotkey={String(i + 1)}
                onPress={() => void fixIssue(it, it.replacements[0] ?? '')}
              />
            ) : (
              <Text dimColor>{it.word}?</Text>
            ),
          )}
        </Box>
        <Box flexDirection="row" flexWrap="wrap" columnGap={1}>
          <Button key="autocorrect" label="Autocorrect" hotkey="a" onPress={() => void autocorrect()} />
          <Button key="light" label="Light" hotkey="l" onPress={() => void draft('light')} />
          <Button key="medium" label="Medium" hotkey="m" onPress={() => void draft('medium')} />
          <Button key="complete" label="Rewrite" hotkey="r" onPress={() => void draft('complete')} />
          <Button key="word" label="Word" hotkey="w" onPress={() => void openWord()} />
          {before !== null ? <Button key="undo" label="Undo" hotkey="u" onPress={() => void restore()} /> : null}
          <Button
            key="autofix"
            label={`Auto-fix: ${mode}`}
            hotkey="x"
            dimColor={mode === 'off'}
            onPress={() => void setAutoMode($, mode === 'off' ? 'on' : mode === 'on' ? 'ai' : 'off')}
          />
          {running || msg ? <Text dimColor>{running ? `${running}…` : msg}</Text> : null}
        </Box>
      </Box>
    )
  })
}

